package com.evidencevault.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="evidence",indexes=@Index(name="idx_evidence_hash",columnList="sha256_hash"))
public class Evidence { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="case_id") private InvestigationCase investigationCase; @Column(nullable=false) private String originalFilename; @Column(nullable=false,unique=true) private String storageFilename; @Column(nullable=false) private String mimeType; @Column(nullable=false) private long fileSize; @Column(name="sha256_hash",nullable=false,length=64) private String sha256Hash; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="uploaded_by") private User uploadedBy; @Column(columnDefinition="TEXT") private String description; @Column(nullable=false,length=30) private String status="ACTIVE"; private LocalDateTime uploadedAt;
 @PrePersist void pre(){uploadedAt=LocalDateTime.now();} public Long getId(){return id;} public InvestigationCase getInvestigationCase(){return investigationCase;} public void setInvestigationCase(InvestigationCase v){investigationCase=v;} public String getOriginalFilename(){return originalFilename;} public void setOriginalFilename(String v){originalFilename=v;} public String getStorageFilename(){return storageFilename;} public void setStorageFilename(String v){storageFilename=v;} public String getMimeType(){return mimeType;} public void setMimeType(String v){mimeType=v;} public long getFileSize(){return fileSize;} public void setFileSize(long v){fileSize=v;} public String getSha256Hash(){return sha256Hash;} public void setSha256Hash(String v){sha256Hash=v;} public User getUploadedBy(){return uploadedBy;} public void setUploadedBy(User v){uploadedBy=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getUploadedAt(){return uploadedAt;} }
